// Nodo de publicacion en Facebook Page + Instagram Business usando la imagen generada de AlquilaBo
const body = $input.first().json.body || $input.first().json;

const pageId = $env.META_PAGE_ID;
const igUserId = $env.META_IG_USER_ID;
const accessToken = $env.META_PAGE_ACCESS_TOKEN;

let fbPostId = body.prev_fb_post_id || null;
let igMediaId = body.prev_ig_media_id || null;
const errors = [];

const generatedImageUrl = body.imagen_generada_url || (Array.isArray(body.fotos) ? body.fotos[0] : null);
const internalImageUrl = body.imagen_generada_internal_url || generatedImageUrl;

// Texto del post con datos recopilados + "Más información en AlquilaBo" y el link de la aplicación abajo
const rawCaption = (body.caption_redes || body.texto_post || '').trim();
const socialCaption = /m[aá]s informaci[oó]n en alquilabo/i.test(rawCaption)
  ? rawCaption
  : `${rawCaption}\n\n✨ Más información en AlquilaBo\n🔗 ${body.url_mapa}`;

if (!accessToken) {
  errors.push('Falta configurar META_PAGE_ACCESS_TOKEN en las variables de entorno de n8n');
} else if (!generatedImageUrl) {
  errors.push('No se encontró la URL de la imagen generada (imagen_generada_url) para publicar');
} else {
  // 1. Publicar la imagen generada en Facebook Page
  if (pageId && !fbPostId) {
    try {
      const isLocalOrPlaceholder = /localhost|127\.0\.0\.1|backend:|tuapp\.com/i.test(generatedImageUrl);
      let fbRes = null;

      if (!isLocalOrPlaceholder) {
        try {
          fbRes = await this.helpers.httpRequest({
            method: 'POST',
            url: `https://graph.facebook.com/v21.0/${pageId}/photos`,
            body: {
              url: generatedImageUrl,
              caption: socialCaption,
              published: true,
              access_token: accessToken,
            },
            json: true,
          });
        } catch (urlErr) {
          fbRes = null;
        }
      }

      // Si el backend corre en red interna de Docker o sin dominio público aún, descargamos el PNG generado y lo subimos como binario a Facebook
      if (!fbRes || (!fbRes.post_id && !fbRes.id)) {
        const imgBuffer = await this.helpers.httpRequest({
          method: 'GET',
          url: internalImageUrl,
          encoding: null,
        });

        fbRes = await this.helpers.httpRequest({
          method: 'POST',
          url: `https://graph.facebook.com/v21.0/${pageId}/photos`,
          formData: {
            caption: socialCaption,
            published: 'true',
            access_token: accessToken,
            source: {
              value: imgBuffer,
              options: {
                filename: `alquilabo-${body.inmueble_id || 'propiedad'}.png`,
                contentType: 'image/png',
              },
            },
          },
          json: true,
        });
      }

      fbPostId = fbRes.post_id || fbRes.id || null;
    } catch (err) {
      errors.push(`Facebook Error: ${err.message || String(err)}`);
    }
  }

  // 2. Publicar la misma imagen generada en Instagram Business
  if (igUserId && !igMediaId) {
    try {
      const singleContainer = await this.helpers.httpRequest({
        method: 'POST',
        url: `https://graph.facebook.com/v21.0/${igUserId}/media`,
        body: {
          image_url: generatedImageUrl,
          caption: socialCaption,
          access_token: accessToken,
        },
        json: true,
      });

      if (singleContainer && singleContainer.id) {
        const publishRes = await this.helpers.httpRequest({
          method: 'POST',
          url: `https://graph.facebook.com/v21.0/${igUserId}/media_publish`,
          body: {
            creation_id: singleContainer.id,
            access_token: accessToken,
          },
          json: true,
        });
        igMediaId = publishRes.id || null;
      }
    } catch (err) {
      errors.push(`Instagram Error: ${err.message || String(err)}`);
    }
  }
}

return [
  {
    json: {
      callback_url: body.callback_url,
      payload: {
        difusion_id: body.difusion_id,
        estado: errors.length > 0 ? 'error' : 'publicado',
        fb_post_id: fbPostId,
        ig_media_id: igMediaId,
        error: errors.length > 0 ? errors.join(' | ') : null,
      },
    },
  },
];
